def is_balanced(s: str) -> bool:
    # 여는 괄호와 닫는 괄호를 매칭하기 위한 딕셔너리
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    closing = set(pairs.keys())

    stack = []

    for char in s:
        if char in opening:
            # 여는 괄호는 스택에 push
            stack.append(char)
        elif char in closing:
            # 닫는 괄호가 나오면 스택 top과 매칭 확인
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
        # 괄호 외 문자는 무시

    # 스택이 비어있어야 모든 괄호가 올바르게 짝지어진 것
    return len(stack) == 0
